import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.bvEHUNtb.js";const u=JSON.parse('{"title":"【序】黄宗羲","description":"黄宗羲序中的邵雍故事、观梅数起源与先天后天之数。","frontmatter":{"title":"【序】黄宗羲","description":"黄宗羲序中的邵雍故事、观梅数起源与先天后天之数。","category":"梅花易数 · 序"},"headers":[],"relativePath":"yijing/meihua-yishu/preface.md","filePath":"yijing/meihua-yishu/preface.md","lastUpdated":1786982540000}'),i={name:"yijing/meihua-yishu/preface.md"};function p(n,t,l,h,s,o){return d(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="【序】黄宗羲" tabindex="-1">【序】黄宗羲 <a class="header-anchor" href="#【序】黄宗羲" aria-label="Permalink to &quot;【序】黄宗羲&quot;">​</a></h1><p>本序作为背景阅读，帮助理解邵雍其人、观梅数的起源，以及“先天之数”“后天之数”这对核心概念。序中的故事不替代卷一正文，而是作为进入全书的历史与精神背景。</p><h2 id="📜-原文" tabindex="-1">📜 原文 <a class="header-anchor" href="#📜-原文" aria-label="Permalink to &quot;📜 原文&quot;">​</a></h2><p>宋庆历中，康节邵先生隐处山林，冬不炉，夏不扇，盖心在于《易》，忘乎其为寒暑也。犹以为未至，糊《易》于壁，心致而目玩焉。邃于《易》理，欲造《易》之数而未又征也。</p><p>一日午睡，有鼠走而前，以所枕瓦枕投击之，鼠走而枕破。觉中有字，取视之：“此枕卖与贤人康节，某年月日某时，击鼠枕破。”先生怪而询之陶家，其陶枕者曰：“昔一人手执《周易》憩坐，举枕其书，必此老也。今不至久矣。吾能识其家。”先生偕陶往访焉，及门，则已不存矣，但遗书一册谓其家人曰：“某年某月某时，有一秀士至吾家，可以此书授之，能终吾身后事矣。”其家以书授先生，先生阅之，乃《易》之文，并有诀例。推例演数，谓其人曰：“汝父存日，有白金置睡床西北窖中，可以营葬事。”其家如言，果得金。</p><p>先生受书以归，后观梅，以雀争胜，布算，知次晚有邻人女折花，堕伤其股。其卜盖始于此，后世相传，遂名《观梅数》。又后算落花之日，午时为马所践毁；又算西林寺额，知有阴人之祸。凡此，皆所谓先天之数也。盖未得卦先得数也。以数起卦，故曰后天。</p><p>若夫见老人有忧色，卜而知老人有食鱼之祸；见少年有喜色，卜而知有婚聘之喜；闻鸡鸣，知鸡必烹；听牛鸣，知牛当杀。凡此，皆后天之数也。盖未得数先得卦也。以卦起数，故曰后天。</p><p>一日，置一椅，以数推之，书椅底曰：“某年月日，当为仙客坐破。”之期，果有道者来访，坐破其椅。仙客愧谢，先生曰：“物之成毁有数，岂足介意，且公神仙也，幸坐以示教。”因举椅下所书以验，道者愕然趋起出，忽不见。乃知数之妙，虽鬼神莫逃，而况于人乎？况于物乎？</p><h2 id="🔤-注音与字词" tabindex="-1">🔤 注音与字词 <a class="header-anchor" href="#🔤-注音与字词" aria-label="Permalink to &quot;🔤 注音与字词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字词</th><th>注音</th><th>释义</th></tr></thead><tbody><tr><td>康节</td><td>Kāng jié</td><td>邵雍的谥号，宋代理学家、易学家</td></tr><tr><td>庆历</td><td>Qìng lì</td><td>宋仁宗年号（1041—1048）</td></tr><tr><td>糊《易》于壁</td><td>—</td><td>把《易经》抄写贴在墙上</td></tr><tr><td>心致而目玩</td><td>—</td><td>心中专注，眼睛反复观看玩味</td></tr><tr><td>邃</td><td>suì</td><td>深入、精通</td></tr><tr><td>未又征</td><td>—</td><td>尚未有验证、实践的机会</td></tr><tr><td>陶家</td><td>—</td><td>制陶的人家</td></tr><tr><td>憩坐</td><td>qì zuò</td><td>休息而坐</td></tr><tr><td>秀士</td><td>—</td><td>有才学的读书人</td></tr><tr><td>白金</td><td>—</td><td>银子</td></tr><tr><td>营葬事</td><td>—</td><td>操办丧葬之事</td></tr><tr><td>布算</td><td>—</td><td>排布数字推算</td></tr><tr><td>先天之数</td><td>—</td><td>未得卦先得数，以数起卦</td></tr><tr><td>后天之数</td><td>—</td><td>未得数先得卦，以卦起数</td></tr><tr><td>愕然趋起</td><td>è rán qū qǐ</td><td>惊愕地站起来快步离去</td></tr></tbody></table><h2 id="📖-白话译文" tabindex="-1">📖 白话译文 <a class="header-anchor" href="#📖-白话译文" aria-label="Permalink to &quot;📖 白话译文&quot;">​</a></h2><p>宋朝庆历年间，康节邵先生隐居山林，冬天不生火炉取暖，夏天不用扇子纳凉——因为心思全在《易》上，早已忘了寒暑冷热。</p><p>他觉得这样还不够，便把《易经》的文字抄写糊贴在墙上，每天心神专注、眼睛反复观玩。他对《易》理已经深入精通，想要进一步探究《易》的数理，却苦于没有机会验证。</p><p>有一天午睡，一只老鼠从他面前跑过，他随手拿枕头投击，鼠跑了，枕头却摔破了。他发现枕头里有字，取出来看：“此枕卖与贤人康节，某年某月某日某时，击鼠枕破。”</p><p>先生觉得奇怪，去询问制作这个枕头的陶家。陶家说：“从前有个人手持《周易》在此休息，把书当枕头垫了一下，一定就是那位老人。他已经很久没来了，我认识他家。”先生随陶家人前去拜访，到了门口，那人已经不在了，只留下一册书，并嘱咐家人：“某年某月某时，会有一位秀士来我家，可以把这本书交给他，他能为我料理身后之事。”</p><p>家人将书交给先生，先生翻阅，发现是《易》的文字，并附有推算的诀法。他按诀法推算，对那家人说：“你父亲在世时，在睡床西北角的地窖里藏有银子，可以用来办理丧事。”那家人按照所说去找，果然找到了银子。</p><p>先生带着书回去。后来有一次观赏梅花，看见两只麻雀争枝，便布算推演，知道第二天傍晚会有邻家女子来折花，失足坠地伤了大腿。这次占卜就是《观梅数》的起源，后世流传，便以此命名。</p><p>此后他又推算落花之日，知道午时花会被马踩毁；又推算西林寺的匾额，知道寺中将有阴人之祸。这些，都是所谓“先天之数”——未得卦先得数，以数起卦，所以叫做先天起卦法；书中此处原文写“故曰后天”，疑为笔误，详见存疑。</p><p>至于见到老人面有忧色，占卜后知道老人将有食鱼之祸；见到少年面有喜色，占卜后知道有婚聘之喜；听到鸡鸣，知道鸡将被烹；听到牛鸣，知道牛将被杀——这些，都是“后天之数”——未得数先得卦，以卦起数，所以叫做后天。</p><p>有一天，他放置了一把椅子，用数推算后，在椅底写道：“某年某月某日，当有仙客坐破此椅。”到了那一天，果然有一位道人来访，坐破了椅子。道人惭愧道歉，先生说：“物之成毁皆有定数，何必在意。您是神仙，请坐下指教。”说完把椅底的字给他看，道人愕然起身，快步走出，忽然不见了。</p><p>由此可知，数之玄妙，连鬼神都逃不过，何况人，何况物？</p><h2 id="🧭-义理解析" tabindex="-1">🧭 义理解析 <a class="header-anchor" href="#🧭-义理解析" aria-label="Permalink to &quot;🧭 义理解析&quot;">​</a></h2><h3 id="一、邵雍其人" tabindex="-1">一、邵雍其人 <a class="header-anchor" href="#一、邵雍其人" aria-label="Permalink to &quot;一、邵雍其人&quot;">​</a></h3><p>邵雍（1011—1077），字尧夫，谥号康节，北宋著名理学家、易学家，与周敦颐、张载、程颢、程颐并称“北宋五子”。他的易学体系以先天象数为核心，认为宇宙万物皆可以数来描述，数背后是象，象背后是理。《梅花易数》正是这套思想的实践应用。</p><p>“冬不炉，夏不扇”不是苦行，而是心已入定，外物不扰。这是一种学习《易》的状态：不是只用脑记，而是用心感。</p><h3 id="二、传书的结构" tabindex="-1">二、传书的结构 <a class="header-anchor" href="#二、传书的结构" aria-label="Permalink to &quot;二、传书的结构&quot;">​</a></h3><p>序里的传书故事有一个值得注意的结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>陶枕里的字（预言）</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>遗书里的字（预言）</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>椅底的字（预言）</span></span></code></pre></div><p>三层预言层层印证。它不只是在说“邵雍很神”，也在传递一个感受：数有前定，象已在先。书还没有传到邵雍手里，枕头里的字就已经写好了。</p><h3 id="三、先天之数与后天之数" tabindex="-1">三、先天之数与后天之数 <a class="header-anchor" href="#三、先天之数与后天之数" aria-label="Permalink to &quot;三、先天之数与后天之数&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>先天之数</th><th>后天之数</th></tr></thead><tbody><tr><td>顺序</td><td>先得数，再起卦</td><td>先得卦，再起数</td></tr><tr><td>触发</td><td>数字（时间、数量、字画）</td><td>象（人的神色、动物鸣叫、外物）</td></tr><tr><td>案例</td><td>观梅、牡丹、西林寺额</td><td>老人忧色、少年喜色、鸡鸣、牛鸣</td></tr><tr><td>本质</td><td>从数入象</td><td>从象入数</td></tr></tbody></table><p>两者殊途同归，都是以易为镜，照见当下。</p><h3 id="四、物之成毁有数" tabindex="-1">四、物之成毁有数 <a class="header-anchor" href="#四、物之成毁有数" aria-label="Permalink to &quot;四、物之成毁有数&quot;">​</a></h3><p>“物之成毁有数”是本序的点睛之句。椅子会被坐破、鼠跑导致枕破、花被马踩，并不只是偶然事件，而是邵雍对宇宙秩序的根本信念：万物皆有象，象皆有数，数皆有理。</p><p>学梅花易数，不只是学“如何预测”，也是学习如何看见那个已经在场的象。</p><h2 id="🌀-象的感悟" tabindex="-1">🌀 象的感悟 <a class="header-anchor" href="#🌀-象的感悟" aria-label="Permalink to &quot;🌀 象的感悟&quot;">​</a></h2><p>读这篇序，一个画面反复出现：一个人把书糊在墙上，每天看。“心致而目玩”——心到了，眼睛在玩。这不是抓取，而是等待；不是急于分析，而是让象的样子慢慢进入自己。</p><p>然后有一天，老鼠跑过，枕头摔破，字显现出来。不是邵雍先去寻找象，而是象自己显现了；他只是准备好了，所以看见了。</p><p>这大概就是梅花易数最根本的姿态：不是我去找象，是象来找我。</p><h2 id="📌-小结" tabindex="-1">📌 小结 <a class="header-anchor" href="#📌-小结" aria-label="Permalink to &quot;📌 小结&quot;">​</a></h2><ul><li>邵雍：北宋理学家，先天象数易学的集大成者，“心在于易，忘乎寒暑”。</li><li>先天之数：以数起卦（数 → 卦）。</li><li>后天之数：以卦起数（卦 → 数）。</li><li>核心信念：物之成毁有数，万象皆有定理。</li><li>学习姿态：心致而目玩，感象而非执文。</li></ul><h2 id="❓-存疑" tabindex="-1">❓ 存疑 <a class="header-anchor" href="#❓-存疑" aria-label="Permalink to &quot;❓ 存疑&quot;">​</a></h2><p>原文疑点：序中说“凡此，皆所谓先天之数也。盖未得卦先得数也。以数起卦，故曰后天。”按逻辑，“以数起卦”应对应“先天”，但原文此处写的是“故曰后天”。同段后文又说“凡此，皆后天之数也。盖未得数先得卦也。以卦起数，故曰后天。”两处都说“故曰后天”，疑为传抄笔误，或黄宗羲序本身有误。</p><p>标记：❓-001。待后续卷一正文“先天后天论”章节对照印证。</p>`,44)])])}const b=a(i,[["render",p]]);export{u as __pageData,b as default};
